package main

import (
	"context"
	"fmt"
	"io"
	"math/rand/v2"
	"net"
	"net/http"
	"net/http/httptrace"
	"sync/atomic"
	"time"

	pb "dylaris-proto/node"
)

// The backup storage speed test: Core presigns one PUT, this node sends
// generated bytes to it and says how long that took, and Core deletes the
// object. It measures this node's way to that storage, which is what a backup
// from here would get.

const maxSpeedTestBytes = 512 << 20

// speedTestTimeout bounds one test. Core waits a little longer for the answer.
var speedTestTimeout = 3 * time.Minute

// speedTestRunning keeps one test at a time on a node: a test fills the
// uplink while it runs, and a second one would only measure the first.
var speedTestRunning atomic.Bool

func (h *StreamHandler) handleStorageSpeedTest(reqID string, req *pb.StorageSpeedTestReq) *pb.NodeMessage {
	if req.GetSizeBytes() <= 0 || req.GetSizeBytes() > maxSpeedTestBytes {
		return errorMsg(reqID, 400, fmt.Sprintf("test size must be 1 byte to %d MB", maxSpeedTestBytes>>20))
	}
	if !speedTestRunning.CompareAndSwap(false, true) {
		return errorMsg(reqID, 409, "a speed test is already running on this node")
	}
	defer speedTestRunning.Store(false)

	n, d, lan, err := runSpeedTest(context.Background(), transferClient(req.GetGuarded(), req.GetAllowPrivate()), req.GetUrl(), req.GetSizeBytes())
	if err != nil {
		return errorMsg(reqID, 502, err.Error())
	}
	return &pb.NodeMessage{RequestId: reqID, Payload: &pb.NodeMessage_StorageSpeedTestResp{
		StorageSpeedTestResp: &pb.StorageSpeedTestResp{Bytes: n, DurationMs: d.Milliseconds(), Lan: lan},
	}}
}

// runSpeedTest PUTs size generated bytes to url. The bytes are pseudo-random
// so nothing on the way can compress them into a better number.
func runSpeedTest(ctx context.Context, client *http.Client, url string, size int64) (int64, time.Duration, bool, error) {
	ctx, cancel := context.WithTimeout(ctx, speedTestTimeout)
	defer cancel()
	var lan atomic.Bool
	ctx = httptrace.WithClientTrace(ctx, &httptrace.ClientTrace{GotConn: func(info httptrace.GotConnInfo) {
		if a, ok := info.Conn.RemoteAddr().(*net.TCPAddr); ok {
			lan.Store(!isPublicUnicast(a.IP))
		}
	}})
	body := io.LimitReader(rand.NewChaCha8([32]byte{'d', 'y', 'l'}), size)
	req, err := http.NewRequestWithContext(ctx, http.MethodPut, url, body)
	if err != nil {
		return 0, 0, false, fmt.Errorf("build request: %w", withoutURL(err))
	}
	req.ContentLength = size
	start := time.Now()
	resp, err := client.Do(req)
	if err != nil {
		return 0, 0, false, fmt.Errorf("upload: %w", withoutURL(err))
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 4096))
	elapsed := time.Since(start)
	if resp.StatusCode/100 != 2 {
		return 0, 0, false, storageStatusError("put", resp)
	}
	return size, elapsed, lan.Load(), nil
}
